import{_ as t,o,c as a,a6 as r}from"./chunks/framework.DtfPIzdJ.js";const p=JSON.parse('{"title":"Cookbook","description":"","frontmatter":{},"headers":[],"relativePath":"cookbook/index.md","filePath":"cookbook/index.md"}'),d={name:"cookbook/index.md"};function i(s,e,n,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="cookbook" tabindex="-1">Cookbook <a class="header-anchor" href="#cookbook" aria-label="Permalink to &quot;Cookbook&quot;">​</a></h1><p>The guide explains how Cluub works; the cookbook shows how to build specific things with it. Each recipe solves one everyday problem, such as a validated form, a paged list or an AI classifier, with a complete, working project you can copy.</p><p>Every recipe has the same parts:</p><ul><li><strong>Problem</strong>: what you&#39;re trying to do, in one paragraph.</li><li><strong>Solution</strong>: the full code, split into files with their exact paths (<code>models/…</code>, <code>services/…</code>, <code>ui/pages/…</code>). The folders are the ones Cluub enforces, so you can drop the files into any project.</li><li><strong>How it works</strong>: the important lines, explained.</li><li><strong>Test it</strong>: a <code>tests/*.test.clb</code> file that passes with <code>cluub test</code>.</li><li><strong>Variations and pitfalls</strong>: common changes, and the things that trip people up, including current limits.</li><li><strong>See also</strong>: where to read more.</li></ul><p>Each recipe was built as a real project (<code>cluub new … --template blank</code>, then the files shown) and passes <code>cluub check</code> with no errors and <code>cluub test</code>, including the tests Cluub generates.</p><h2 id="recipes" tabindex="-1">Recipes <a class="header-anchor" href="#recipes" aria-label="Permalink to &quot;Recipes&quot;">​</a></h2><h3 id="data-and-pages" tabindex="-1">Data and pages <a class="header-anchor" href="#data-and-pages" aria-label="Permalink to &quot;Data and pages&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Recipe</th><th>What you&#39;ll build</th></tr></thead><tbody><tr><td><a href="/home/cookbook/forms-validation">Forms with validation</a></td><td>A sign-up form with live hints, a disabled submit button, and server errors shown next to the right field</td></tr><tr><td><a href="/home/cookbook/crud-list">CRUD list</a></td><td>A bookmark list with create, inline edit and delete</td></tr><tr><td><a href="/home/cookbook/search-filter">Search and filtering</a></td><td>Server-side search with query parameters, plus instant filtering in the view</td></tr><tr><td><a href="/home/cookbook/master-detail">Master–detail pages</a></td><td>A list that links to <code>/books/{id}</code>, with a spinner and a friendly &quot;not found&quot;</td></tr><tr><td><a href="/home/cookbook/pagination">Pagination in a service</a></td><td>&quot;Page 2 of 7&quot; with Previous/Next, cut and clamped in the service</td></tr><tr><td><a href="/home/cookbook/loading-empty-states">Loading and empty states</a></td><td>Spinner, load error with retry, empty state and busy buttons</td></tr><tr><td><a href="/home/cookbook/json-file-store">Persisting data to a JSON file</a></td><td>A journal that survives restarts, and what happens when models change</td></tr></tbody></table><h3 id="backend-and-integration" tabindex="-1">Backend and integration <a class="header-anchor" href="#backend-and-integration" aria-label="Permalink to &quot;Backend and integration&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Recipe</th><th>What you&#39;ll build</th></tr></thead><tbody><tr><td><a href="/home/cookbook/external-api">Calling an external REST API</a></td><td>A weather lookup with <code>client</code>, friendly <code>NetworkError</code> handling and testable JSON mapping</td></tr><tr><td><a href="/home/cookbook/error-handling">Error-handling patterns</a></td><td><code>require</code>, <code>fail … status</code>, <code>get</code> vs <code>find</code> and <code>try … catch problem</code>, each with its own status code</td></tr></tbody></table><h3 id="ai" tabindex="-1">AI <a class="header-anchor" href="#ai" aria-label="Permalink to &quot;AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Recipe</th><th>What you&#39;ll build</th></tr></thead><tbody><tr><td><a href="/home/cookbook/ai-summarize">AI: summarizing text</a></td><td>Summaries in three styles with a system prompt and a history</td></tr><tr><td><a href="/home/cookbook/ai-extraction">AI: structured extraction</a></td><td>Sales emails turned into validated <code>Lead</code> records with <code>as Lead</code></td></tr><tr><td><a href="/home/cookbook/ai-classification">AI: classification</a></td><td>Support tickets labeled with <code>as one of</code>, routed by code, and correctable by people</td></tr><tr><td><a href="/home/cookbook/chat-assistant">A chat assistant</a></td><td>A bookshop assistant with a persona, a 10-message memory and starter questions</td></tr></tbody></table><h3 id="ui-building-blocks" tabindex="-1">UI building blocks <a class="header-anchor" href="#ui-building-blocks" aria-label="Permalink to &quot;UI building blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Recipe</th><th>What you&#39;ll build</th></tr></thead><tbody><tr><td><a href="/home/cookbook/reusable-components">Reusable components</a></td><td>A task board from nested components that call the page&#39;s actions</td></tr><tr><td><a href="/home/cookbook/theming">Custom theme and styling</a></td><td>Brand colors, dark mode, a logo, <code>style</code> words and dynamic <code>class</code>es</td></tr></tbody></table><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>Create a project with <code>cluub new my-app --template blank</code> and add the files from a recipe. Delete the template&#39;s <code>ui/pages/home.clb</code> if the recipe has its own page at <code>/</code>.</li><li>Recipes that use AI run their tests <strong>without a key</strong>: in tests, <code>ask ai</code> returns <code>&quot;AI reply to: …&quot;</code>, <code>as one of</code> returns the first option, and <code>as Model</code> returns a valid sample. To use a real model, copy <code>.env.example</code> to <code>.env</code> and add a key (see <a href="/home/guide/ai">AI</a>).</li><li>Clients never reach the network in tests; they return <code>nothing</code>. The <a href="/home/cookbook/external-api">external API recipe</a> shows how to test around that.</li><li>Things Cluub doesn&#39;t have yet (auth and sessions, databases, file uploads, component state, debounce, streaming) are noted in the recipes where they matter, with the closest honest approach. See <a href="/home/reference/roadmap">Status &amp; roadmap</a>.</li></ul>',16)])])}const b=t(d,[["render",i]]);export{p as __pageData,b as default};
